  "summary": "The code contains critical security vulnerabilities including LDAP injection and improper resource management. The overall health is poor due to lack of error handling and hardcoded configurations. The fixed code implements input sanitization, connection pooling via context managers, and robust error handling.",
  "fixed_code": "from flask import request, Flask, abort\nimport ldap3\nimport os\nfrom ldap3.utils.conv import escape_filter_chars\n\napp = Flask(__name__)\n\nALLOWED_DCS = {'example', 'corp'}\n\n@app.route(\"/normal\")\ndef normal() -> str:\n    unsafe_dc = request.args.get('dc')\n    unsafe_filter = request.args.get('username')\n\n    if unsafe_dc not in ALLOWED_DCS:\n        abort(400, \"Invalid domain component\")\n\n    dn = f\"dc={unsafe_dc}\"\n    search_filter = f\"(user={escape_filter_chars(unsafe_filter)})\"\n\n    ldap_server = os.getenv('LDAP_SERVER', 'ldap://127.0.0.1')\n    srv = ldap3.Server(ldap_server)\n    \n    try:\n        with ldap3.Connection(srv, user=dn, auto_bind=True) as conn:\n            result = conn.search(dn, search_filter)\n            return str(result)\n    except ldap3.core.exceptions.LDAPException as e:\n        app.logger.error(f\"LDAP error: {e}\")\n        abort(500, \"Internal LDAP error\")"
}
